function validate([moves]) {
  if (!Array.isArray(moves) || moves.length < 1 || moves.length > 9) return 'moves needs 1 to 9 moves.';
  const board = new Array(9).fill(0);
  const lines = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];
  for (let i = 0; i < moves.length; i++) {
    const move = moves[i];
    if (!Array.isArray(move) || move.length !== 2 || !move.every(v => Number.isInteger(v) && v >= 0 && v <= 2)) return 'Each move is [row, col] with values from 0 to 2.';
    if (lines.some(([a, b, c]) => board[a] && board[a] === board[b] && board[b] === board[c])) return 'No move may come after someone has won.';
    const cell = move[0] * 3 + move[1];
    if (board[cell]) return 'Each cell can be marked only once.';
    board[cell] = i % 2 === 0 ? 1 : 2;
  }
  return null;
}

