function tictactoe(moves) {
  const rows = [0, 0, 0];
  const cols = [0, 0, 0];
  let diagonal = 0;
  let antiDiagonal = 0;

  for (let i = 0; i < moves.length; i++) {
    const [row, col] = moves[i];
    const mark = i % 2 === 0 ? 1 : -1;
    rows[row] += mark;
    cols[col] += mark;
    if (row === col) {
      diagonal += mark;
    }
    if (row + col === 2) {
      antiDiagonal += mark;
    }
    const won = Math.abs(rows[row]) === 3 || Math.abs(cols[col]) === 3 || Math.abs(diagonal) === 3 || Math.abs(antiDiagonal) === 3;
    if (won) {
      return mark === 1 ? "A" : "B";
    }
  }
  return moves.length === 9 ? "Draw" : "Pending";
}

