function tictactoe(moves) {
  const grid = [[' ', ' ', ' '], [' ', ' ', ' '], [' ', ' ', ' ']];
  moves.forEach(([r, c], turn) => { grid[r][c] = turn % 2 === 0 ? 'X' : 'O'; });
  const lines = [];
  for (let k = 0; k < 3; k++) {
    lines.push([grid[k][0], grid[k][1], grid[k][2]]);
    lines.push([grid[0][k], grid[1][k], grid[2][k]]);
  }
  lines.push([grid[0][0], grid[1][1], grid[2][2]]);
  lines.push([grid[0][2], grid[1][1], grid[2][0]]);
  for (const line of lines) {
    if (line.every(ch => ch === 'X')) return 'A';
    if (line.every(ch => ch === 'O')) return 'B';
  }
  return moves.length === 9 ? 'Draw' : 'Pending';
}

