function generate(rand, size) {
  const cells = [0, 1, 2, 3, 4, 5, 6, 7, 8];
  for (let i = 8; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [cells[i], cells[j]] = [cells[j], cells[i]];
  }
  // Large games play on until someone wins or the board fills; small ones may stop at any point.
  const limit = size === 'large' ? 9 : 1 + Math.floor(rand() * 9);
  const board = new Array(9).fill(0);
  const lines = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];
  const moves = [];
  for (let i = 0; i < limit; i++) {
    board[cells[i]] = i % 2 === 0 ? 1 : 2;
    moves.push([Math.floor(cells[i] / 3), cells[i] % 3]);
    if (lines.some(([a, b, c]) => board[a] && board[a] === board[b] && board[b] === board[c])) break;
  }
  return [moves];
}
